  'Eco mode limits network requests. Covers already saved or cached stay visible. New covers are not downloaded: the name appears in a square that follows the theme, with its own color for the border and the text. Pure black turns on to save battery. Automatic cover downloads stop, and the player no longer fetches a cover only to tint the screen.': '에코 모드는 요청을 줄입니다. 이미 저장되었거나 캐시된 표지는 그대로 보입니다. 새 표지는 받지 않습니다. 이름은 테마를 따르는 사각형에, 테두리와 글자는 고유한 색으로 표시됩니다. 배터리를 아끼려고 순수 검정이 켜집니다. 표지 자동 다운로드가 멈추고, 화면 색을 위해 표지를 받지 않습니다.',
